class Snippet extends DataClass implements Insertable<Snippet> {
  final String id;
  final String label;
  final String command;

  /// Optional category for grouping snippets (e.g. 'Docker', 'Git', 'System')
  final String? category;

  /// Show confirmation dialog before executing.
  final bool confirmBeforeRun;

  /// Whether this is a built-in default snippet (not deletable by free users).
  final bool isDefault;

  /// Optional JSON metadata (schema v23): a snippet description and per-variable
  /// descriptions. Shape: `{"description": "…", "variables": {"NAME": "…"}}`.
  /// Nullable - untouched snippets store NULL. Variable *defaults* live in the
  /// command (`${VAR:-default}`), not here. Decoded via `parseSnippetMetadata`.
  final String? metadata;
  final int sortOrder;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Snippet({
    required this.id,
    required this.label,
    required this.command,
    this.category,
    required this.confirmBeforeRun,
    required this.isDefault,
    this.metadata,
    required this.sortOrder,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['label'] = Variable<String>(label);
    map['command'] = Variable<String>(command);
    if (!nullToAbsent || category != null) {
      map['category'] = Variable<String>(category);
    }
    map['confirm_before_run'] = Variable<bool>(confirmBeforeRun);
    map['is_default'] = Variable<bool>(isDefault);
    if (!nullToAbsent || metadata != null) {
      map['metadata'] = Variable<String>(metadata);
    }
    map['sort_order'] = Variable<int>(sortOrder);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  SnippetsCompanion toCompanion(bool nullToAbsent) {
    return SnippetsCompanion(
      id: Value(id),
      label: Value(label),
      command: Value(command),
      category: category == null && nullToAbsent
          ? const Value.absent()
          : Value(category),
      confirmBeforeRun: Value(confirmBeforeRun),
      isDefault: Value(isDefault),
      metadata: metadata == null && nullToAbsent
          ? const Value.absent()
          : Value(metadata),
      sortOrder: Value(sortOrder),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Snippet.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Snippet(
      id: serializer.fromJson<String>(json['id']),
      label: serializer.fromJson<String>(json['label']),
      command: serializer.fromJson<String>(json['command']),
      category: serializer.fromJson<String?>(json['category']),
      confirmBeforeRun: serializer.fromJson<bool>(json['confirmBeforeRun']),
      isDefault: serializer.fromJson<bool>(json['isDefault']),
      metadata: serializer.fromJson<String?>(json['metadata']),
      sortOrder: serializer.fromJson<int>(json['sortOrder']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'label': serializer.toJson<String>(label),
      'command': serializer.toJson<String>(command),
      'category': serializer.toJson<String?>(category),
      'confirmBeforeRun': serializer.toJson<bool>(confirmBeforeRun),
      'isDefault': serializer.toJson<bool>(isDefault),
      'metadata': serializer.toJson<String?>(metadata),
      'sortOrder': serializer.toJson<int>(sortOrder),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  Snippet copyWith({
    String? id,
    String? label,
    String? command,
    Value<String?> category = const Value.absent(),
    bool? confirmBeforeRun,
    bool? isDefault,
    Value<String?> metadata = const Value.absent(),
    int? sortOrder,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => Snippet(
    id: id ?? this.id,
    label: label ?? this.label,
    command: command ?? this.command,
    category: category.present ? category.value : this.category,
    confirmBeforeRun: confirmBeforeRun ?? this.confirmBeforeRun,
    isDefault: isDefault ?? this.isDefault,
    metadata: metadata.present ? metadata.value : this.metadata,
    sortOrder: sortOrder ?? this.sortOrder,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  Snippet copyWithCompanion(SnippetsCompanion data) {
    return Snippet(
      id: data.id.present ? data.id.value : this.id,
      label: data.label.present ? data.label.value : this.label,
      command: data.command.present ? data.command.value : this.command,
      category: data.category.present ? data.category.value : this.category,
      confirmBeforeRun: data.confirmBeforeRun.present
          ? data.confirmBeforeRun.value
          : this.confirmBeforeRun,
      isDefault: data.isDefault.present ? data.isDefault.value : this.isDefault,
      metadata: data.metadata.present ? data.metadata.value : this.metadata,
      sortOrder: data.sortOrder.present ? data.sortOrder.value : this.sortOrder,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Snippet(')
          ..write('id: $id, ')
          ..write('label: $label, ')
          ..write('command: $command, ')
          ..write('category: $category, ')
          ..write('confirmBeforeRun: $confirmBeforeRun, ')
          ..write('isDefault: $isDefault, ')
          ..write('metadata: $metadata, ')
          ..write('sortOrder: $sortOrder, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    label,
    command,
    category,
    confirmBeforeRun,
    isDefault,
    metadata,
    sortOrder,
    createdAt,
    updatedAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Snippet &&
          other.id == this.id &&
          other.label == this.label &&
          other.command == this.command &&
          other.category == this.category &&
          other.confirmBeforeRun == this.confirmBeforeRun &&
          other.isDefault == this.isDefault &&
          other.metadata == this.metadata &&
          other.sortOrder == this.sortOrder &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt);
}

