  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['host'] = Variable<String>(host);
    map['port'] = Variable<int>(port);
    map['key_type'] = Variable<String>(keyType);
    map['fingerprint'] = Variable<String>(fingerprint);
    map['public_key_base64'] = Variable<String>(publicKeyBase64);
    map['first_seen'] = Variable<DateTime>(firstSeen);
    map['last_seen'] = Variable<DateTime>(lastSeen);
    if (!nullToAbsent || recordedDevice != null) {
      map['recorded_device'] = Variable<String>(recordedDevice);
    }
    map['locally_verified'] = Variable<bool>(locallyVerified);
    if (!nullToAbsent || viaScope != null) {
      map['via_scope'] = Variable<String>(viaScope);
    }
    return map;
  }

  KnownHostsCompanion toCompanion(bool nullToAbsent) {
    return KnownHostsCompanion(
      id: Value(id),
      host: Value(host),
      port: Value(port),
      keyType: Value(keyType),
      fingerprint: Value(fingerprint),
      publicKeyBase64: Value(publicKeyBase64),
      firstSeen: Value(firstSeen),
      lastSeen: Value(lastSeen),
      recordedDevice: recordedDevice == null && nullToAbsent
          ? const Value.absent()
          : Value(recordedDevice),
      locallyVerified: Value(locallyVerified),
      viaScope: viaScope == null && nullToAbsent
          ? const Value.absent()
