class WorkflowRow extends DataClass implements Insertable<WorkflowRow> {
  final String id;
  final String name;
  final String? description;

  /// JSON-encoded list of WorkflowStep objects.
  final String stepsJson;

  /// Whether the workflow is enabled (can be triggered externally).
  final bool enabled;

  /// Whether to send a notification on failure.
  final bool notifyOnFailure;

  /// Whether to send a notification on success.
  final bool notifyOnSuccess;
  final DateTime createdAt;
  final DateTime? lastRunAt;
  const WorkflowRow({
    required this.id,
    required this.name,
    this.description,
    required this.stepsJson,
    required this.enabled,
    required this.notifyOnFailure,
    required this.notifyOnSuccess,
    required this.createdAt,
    this.lastRunAt,
  });
