      map['description'] = Variable<String>(description);
    }
    map['steps_json'] = Variable<String>(stepsJson);
    map['enabled'] = Variable<bool>(enabled);
    map['notify_on_failure'] = Variable<bool>(notifyOnFailure);
    map['notify_on_success'] = Variable<bool>(notifyOnSuccess);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || lastRunAt != null) {
      map['last_run_at'] = Variable<DateTime>(lastRunAt);
    }
    return map;
  }

  WorkflowsCompanion toCompanion(bool nullToAbsent) {
    return WorkflowsCompanion(
      id: Value(id),
      name: Value(name),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
      stepsJson: Value(stepsJson),
      enabled: Value(enabled),
      notifyOnFailure: Value(notifyOnFailure),
      notifyOnSuccess: Value(notifyOnSuccess),
      createdAt: Value(createdAt),
      lastRunAt: lastRunAt == null && nullToAbsent
          ? const Value.absent()
          : Value(lastRunAt),
    );
