    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['pattern'] = Variable<String>(pattern);
    map['case_sensitive'] = Variable<bool>(caseSensitive);
    map['notify'] = Variable<bool>(notify);
    map['highlight'] = Variable<bool>(highlight);
    if (!nullToAbsent || highlightColor != null) {
      map['highlight_color'] = Variable<int>(highlightColor);
    }
    map['play_sound'] = Variable<bool>(playSound);
    if (!nullToAbsent || connectionId != null) {
      map['connection_id'] = Variable<String>(connectionId);
    }
    map['enabled'] = Variable<bool>(enabled);
    map['sort_order'] = Variable<int>(sortOrder);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || updatedAt != null) {
      map['updated_at'] = Variable<DateTime>(updatedAt);
    }
    return map;
  }

  TerminalTriggersCompanion toCompanion(bool nullToAbsent) {
    return TerminalTriggersCompanion(
      id: Value(id),
      name: Value(name),
      pattern: Value(pattern),
      caseSensitive: Value(caseSensitive),
