class CommandHistoryEntry extends DataClass
    implements Insertable<CommandHistoryEntry> {
  final String id;

  /// The exact command line the user ran.
  final String command;

  /// The host it ran on, or NULL when unknown. Plain id (no FK): a deleted host
  /// simply loses its back-reference, which is harmless.
  final String? connectionId;

  /// Denormalised host label, so history stays readable after the host record
  /// is gone.
  final String? hostLabel;
  final DateTime createdAt;

  /// Nullable + auto-bumped by the universal newest-wins trigger; drives sync.
  final DateTime? updatedAt;

  /// The command's exit status, or NULL when the shell did not report one.
  final int? exitCode;

  /// How long the command ran, in milliseconds, or NULL when not measured.
  final int? durationMs;

  /// The working directory the command ran in (from OSC 7), or NULL.
  final String? cwd;
  const CommandHistoryEntry({
    required this.id,
    required this.command,
    this.connectionId,
    this.hostLabel,
    required this.createdAt,
    this.updatedAt,
    this.exitCode,
    this.durationMs,
    this.cwd,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['command'] = Variable<String>(command);
    if (!nullToAbsent || connectionId != null) {
      map['connection_id'] = Variable<String>(connectionId);
    }
    if (!nullToAbsent || hostLabel != null) {
      map['host_label'] = Variable<String>(hostLabel);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || updatedAt != null) {
      map['updated_at'] = Variable<DateTime>(updatedAt);
    }
    if (!nullToAbsent || exitCode != null) {
      map['exit_code'] = Variable<int>(exitCode);
    }
    if (!nullToAbsent || durationMs != null) {
      map['duration_ms'] = Variable<int>(durationMs);
    }
    if (!nullToAbsent || cwd != null) {
      map['cwd'] = Variable<String>(cwd);
    }
    return map;
  }

  CommandHistoryCompanion toCompanion(bool nullToAbsent) {
    return CommandHistoryCompanion(
      id: Value(id),
      command: Value(command),
      connectionId: connectionId == null && nullToAbsent
          ? const Value.absent()
          : Value(connectionId),
      hostLabel: hostLabel == null && nullToAbsent
          ? const Value.absent()
          : Value(hostLabel),
      createdAt: Value(createdAt),
      updatedAt: updatedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(updatedAt),
      exitCode: exitCode == null && nullToAbsent
          ? const Value.absent()
          : Value(exitCode),
      durationMs: durationMs == null && nullToAbsent
          ? const Value.absent()
          : Value(durationMs),
      cwd: cwd == null && nullToAbsent ? const Value.absent() : Value(cwd),
    );
