      map['name'] = Variable<String>(name);
    }
    map['level'] = Variable<String>(level);
    map['switches'] = Variable<String>(switches);
    map['owners_only'] = Variable<bool>(ownersOnly);
    map['allow'] = Variable<String>(allow);
    map['rotation_due'] = Variable<bool>(rotationDue);
    map['confirm_reveal'] = Variable<bool>(confirmReveal);
    map['key_generation'] = Variable<int>(keyGeneration);
    map['last_revision'] = Variable<int>(lastRevision);
    return map;
  }

