class OrchardRecordRow extends DataClass
    implements Insertable<OrchardRecordRow> {
  final int seq;

  /// The hash of the entry before; empty for the first.
  final Uint8List prev;
  final String type;

  /// The body exactly as signed.
  final String body;
  final String byUid;
  final int byKeyVersion;
  final Uint8List signature;

  /// This entry's hash: what the next names as its prev, and what an item
  /// written after it names as its anchor.
  final Uint8List hash;

  /// When this device first saw the entry, in seconds since the epoch (3.0):
  /// entries carry no time, so the Trust page shows this
  /// instead. Kept here only, never sent. Null for entries kept before it
  /// was noted.
  final int? firstSeen;
  const OrchardRecordRow({
    required this.seq,
    required this.prev,
    required this.type,
    required this.body,
    required this.byUid,
    required this.byKeyVersion,
    required this.signature,
    required this.hash,
    this.firstSeen,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['seq'] = Variable<int>(seq);
    map['prev'] = Variable<Uint8List>(prev);
    map['type'] = Variable<String>(type);
    map['body'] = Variable<String>(body);
    map['by_uid'] = Variable<String>(byUid);
    map['by_key_version'] = Variable<int>(byKeyVersion);
    map['signature'] = Variable<Uint8List>(signature);
    map['hash'] = Variable<Uint8List>(hash);
    if (!nullToAbsent || firstSeen != null) {
      map['first_seen'] = Variable<int>(firstSeen);
    }
    return map;
  }

  OrchardRecordEntriesCompanion toCompanion(bool nullToAbsent) {
    return OrchardRecordEntriesCompanion(
      seq: Value(seq),
      prev: Value(prev),
      type: Value(type),
      body: Value(body),
      byUid: Value(byUid),
      byKeyVersion: Value(byKeyVersion),
      signature: Value(signature),
      hash: Value(hash),
      firstSeen: firstSeen == null && nullToAbsent
          ? const Value.absent()
          : Value(firstSeen),
    );
  }

  factory OrchardRecordRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return OrchardRecordRow(
      seq: serializer.fromJson<int>(json['seq']),
      prev: serializer.fromJson<Uint8List>(json['prev']),
      type: serializer.fromJson<String>(json['type']),
      body: serializer.fromJson<String>(json['body']),
      byUid: serializer.fromJson<String>(json['byUid']),
      byKeyVersion: serializer.fromJson<int>(json['byKeyVersion']),
      signature: serializer.fromJson<Uint8List>(json['signature']),
      hash: serializer.fromJson<Uint8List>(json['hash']),
      firstSeen: serializer.fromJson<int?>(json['firstSeen']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'seq': serializer.toJson<int>(seq),
      'prev': serializer.toJson<Uint8List>(prev),
      'type': serializer.toJson<String>(type),
      'body': serializer.toJson<String>(body),
      'byUid': serializer.toJson<String>(byUid),
      'byKeyVersion': serializer.toJson<int>(byKeyVersion),
      'signature': serializer.toJson<Uint8List>(signature),
      'hash': serializer.toJson<Uint8List>(hash),
      'firstSeen': serializer.toJson<int?>(firstSeen),
    };
  }

  OrchardRecordRow copyWith({
    int? seq,
    Uint8List? prev,
    String? type,
    String? body,
    String? byUid,
    int? byKeyVersion,
    Uint8List? signature,
    Uint8List? hash,
    Value<int?> firstSeen = const Value.absent(),
  }) => OrchardRecordRow(
    seq: seq ?? this.seq,
    prev: prev ?? this.prev,
    type: type ?? this.type,
    body: body ?? this.body,
    byUid: byUid ?? this.byUid,
    byKeyVersion: byKeyVersion ?? this.byKeyVersion,
    signature: signature ?? this.signature,
    hash: hash ?? this.hash,
    firstSeen: firstSeen.present ? firstSeen.value : this.firstSeen,
  );
  OrchardRecordRow copyWithCompanion(OrchardRecordEntriesCompanion data) {
    return OrchardRecordRow(
      seq: data.seq.present ? data.seq.value : this.seq,
      prev: data.prev.present ? data.prev.value : this.prev,
      type: data.type.present ? data.type.value : this.type,
      body: data.body.present ? data.body.value : this.body,
      byUid: data.byUid.present ? data.byUid.value : this.byUid,
      byKeyVersion: data.byKeyVersion.present
          ? data.byKeyVersion.value
          : this.byKeyVersion,
      signature: data.signature.present ? data.signature.value : this.signature,
      hash: data.hash.present ? data.hash.value : this.hash,
      firstSeen: data.firstSeen.present ? data.firstSeen.value : this.firstSeen,
    );
  }

  @override
  String toString() {
    return (StringBuffer('OrchardRecordRow(')
          ..write('seq: $seq, ')
          ..write('prev: $prev, ')
          ..write('type: $type, ')
          ..write('body: $body, ')
          ..write('byUid: $byUid, ')
          ..write('byKeyVersion: $byKeyVersion, ')
          ..write('signature: $signature, ')
          ..write('hash: $hash, ')
          ..write('firstSeen: $firstSeen')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    seq,
    $driftBlobEquality.hash(prev),
    type,
    body,
    byUid,
    byKeyVersion,
    $driftBlobEquality.hash(signature),
    $driftBlobEquality.hash(hash),
    firstSeen,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is OrchardRecordRow &&
          other.seq == this.seq &&
          $driftBlobEquality.equals(other.prev, this.prev) &&
          other.type == this.type &&
          other.body == this.body &&
          other.byUid == this.byUid &&
          other.byKeyVersion == this.byKeyVersion &&
          $driftBlobEquality.equals(other.signature, this.signature) &&
          $driftBlobEquality.equals(other.hash, this.hash) &&
          other.firstSeen == this.firstSeen);
}

