class SupportTicketRow extends DataClass
    implements Insertable<SupportTicketRow> {
  /// The nonce the ticket was sent with (uuid). The key here because it
  /// exists before the server has answered.
  final String nonce;

  /// The server's id for the ticket, once it has arrived. Null while a
  /// support ticket written offline is still waiting to be sent.
  final String? serverId;

  /// The number people say out loud (#10042). Null until it has arrived.
  final int? number;

  /// 32 random bytes, base64url. See the class comment.
  final String token;

  /// `support`, `bug` or `suggestion`.
  final String type;
  final String title;

  /// `open` or `closed` as the server last said, or `gone` once the server
  /// no longer has it (a private ticket is deleted 90 days after it closed).
  final String status;

  /// Who is waited on, as the server last said: `staff`, `user` or null.
  final String? awaiting;

  /// The forum tags of a public report (a JSON list of names).
  final String tags;

  /// The forum post of a public report. Always null for a support ticket.
  final String? discordUrl;

  /// Epoch milliseconds.
  final int createdAt;
  final int? lastMessageAt;
  final int messageCount;

  /// The newest follow-up and who wrote it (`user` or `staff`), as the server
  /// last said. A reply is unread while this is a staff message that is not
  /// [lastSeenMessageId].
  final String? lastMessageId;
  final String? lastMessageFrom;

  /// The newest follow-up the person has had on screen.
  final String? lastSeenMessageId;

  /// The newest follow-up a notification was shown for, so one reply never
  /// notifies twice.
  final String? notifiedMessageId;

  /// The conversation as last read (JSON), so it can be read with no
  /// network: the opening text and the follow-ups.
  final String? conversation;

  /// A support ticket that has not reached the server yet: the request that
  /// will be sent (JSON). Null once it has arrived, and always null for a
  /// report (an unsent report waits in the report queue).
  final String? pending;

  /// Why a waiting ticket will not be sent again: `blocked`, `account`
  /// (the account was to be included and is no longer signed in) or
  /// `rejected`. Null while it is still being tried.
  final String? sendError;
  const SupportTicketRow({
    required this.nonce,
    this.serverId,
    this.number,
    required this.token,
    required this.type,
    required this.title,
    required this.status,
    this.awaiting,
    required this.tags,
    this.discordUrl,
    required this.createdAt,
    this.lastMessageAt,
    required this.messageCount,
    this.lastMessageId,
    this.lastMessageFrom,
    this.lastSeenMessageId,
    this.notifiedMessageId,
    this.conversation,
    this.pending,
    this.sendError,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['nonce'] = Variable<String>(nonce);
    if (!nullToAbsent || serverId != null) {
      map['server_id'] = Variable<String>(serverId);
    }
    if (!nullToAbsent || number != null) {
      map['number'] = Variable<int>(number);
    }
    map['token'] = Variable<String>(token);
    map['type'] = Variable<String>(type);
    map['title'] = Variable<String>(title);
    map['status'] = Variable<String>(status);
    if (!nullToAbsent || awaiting != null) {
      map['awaiting'] = Variable<String>(awaiting);
    }
    map['tags'] = Variable<String>(tags);
    if (!nullToAbsent || discordUrl != null) {
      map['discord_url'] = Variable<String>(discordUrl);
    }
    map['created_at'] = Variable<int>(createdAt);
    if (!nullToAbsent || lastMessageAt != null) {
      map['last_message_at'] = Variable<int>(lastMessageAt);
    }
    map['message_count'] = Variable<int>(messageCount);
    if (!nullToAbsent || lastMessageId != null) {
      map['last_message_id'] = Variable<String>(lastMessageId);
    }
    if (!nullToAbsent || lastMessageFrom != null) {
      map['last_message_from'] = Variable<String>(lastMessageFrom);
    }
    if (!nullToAbsent || lastSeenMessageId != null) {
      map['last_seen_message_id'] = Variable<String>(lastSeenMessageId);
    }
    if (!nullToAbsent || notifiedMessageId != null) {
      map['notified_message_id'] = Variable<String>(notifiedMessageId);
    }
    if (!nullToAbsent || conversation != null) {
      map['conversation'] = Variable<String>(conversation);
    }
    if (!nullToAbsent || pending != null) {
      map['pending'] = Variable<String>(pending);
    }
    if (!nullToAbsent || sendError != null) {
      map['send_error'] = Variable<String>(sendError);
    }
    return map;
  }

