    map['ticket_nonce'] = Variable<String>(ticketNonce);
    map['body'] = Variable<String>(body);
    map['created_at'] = Variable<int>(createdAt);
    if (!nullToAbsent || error != null) {
      map['error'] = Variable<String>(error);
    }
    return map;
  }

  TicketOutboxCompanion toCompanion(bool nullToAbsent) {
    return TicketOutboxCompanion(
      nonce: Value(nonce),
      ticketNonce: Value(ticketNonce),
      body: Value(body),
      createdAt: Value(createdAt),
      error: error == null && nullToAbsent
          ? const Value.absent()
          : Value(error),
    );
  }

